use core.game

struct Ball { x: Float, y: Float, vx: Float, vy: Float }

fn run() {
    g :: Game.window(title: "Breakout", width: 960, height: 540)
    ball := Ball.{ x: 480.0, y: 420.0, vx: 220.0, vy: -180.0 }

    g.each_frame((frame) => {
        ball.x += ball.vx * frame.seconds
        ball.y += ball.vy * frame.seconds

        if frame.input.key_down(.Left) { ball.x -= 300.0 * frame.seconds }
        if frame.input.key_down(.Right) { ball.x += 300.0 * frame.seconds }

        frame.draw.clear(Color.rgb(12, 16, 24))
        frame.draw.circle(ball.x, ball.y, 8.0, Color.white())
    })
}

use core.game

struct Breakout { ball: Ball, score: Int }

fn run() {
    Game.run(App<Breakout>.{
        title: "Breakout",
        size: Size.{ width: 960, height: 540 },
        init: () => Breakout.new(),
        update: (&game, frame) => {
            game.ball.step(frame.seconds, frame.input)
            if game.ball.hit_bottom() { game.score = 0 }
        },
        draw: (game, canvas) => {
            canvas.clear(Color.rgb(12, 16, 24))
            canvas.circle(game.ball.x, game.ball.y, 8.0, Color.white())
            canvas.text("score {game.score}", 24.0, 24.0)
        },
    })
}

use core.game

fn run() {
    scene := Scene.new()
    paddle := scene.sprite("paddle", "assets/paddle.png").at(480.0, 500.0)
    ball := scene.circle("ball", radius: 8.0).at(480.0, 420.0)
    ball.velocity = Vec2.{ x: 220.0, y: -180.0 }

    scene.on_frame((frame) => {
        paddle.x = 480.0 + frame.input.axis(.Horizontal) * 360.0
        ball.move(ball.velocity * frame.seconds)

        if ball.overlaps(paddle) { ball.velocity.y = -ball.velocity.y }
        if ball.y < 0.0 { ball.velocity.y = -ball.velocity.y }
    })

    Game.play(scene, title: "Breakout", size: Size.{ width: 960, height: 540 })
}

