use core.game

struct Position { x: Float, y: Float }
struct Velocity { x: Float, y: Float }

fn run() {
    world := World.new()
    world.spawn((Sprite.from("assets/ball.png"), Position.{ x: 480.0, y: 420.0 }, Velocity.{ x: 220.0, y: -180.0 }))

    world.system((q: Query<(&Position, &Velocity)>, frame: Frame) => {
        loop (pos, vel) in q {
            pos.x += vel.x * frame.seconds
            pos.y += vel.y * frame.seconds
        }
    })

    Game.play(world, title: "Breakout", size: Size.{ width: 960, height: 540 })
}

